#!/usr/bin/env bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). MIT License.
# Installs Proton Updater for the current user: app files, menu entry and a timer.
# (every 30 min: apply pending switches, check for new versions every 12 h)
set -euo pipefail
SRC="$(cd "$(dirname "$0")" && pwd)"
APP="$HOME/.local/share/proton-updater"

command -v python3 >/dev/null || { echo "python3 is required."; exit 1; }
if ! python3 -c "import PySide6" 2>/dev/null; then
  echo "PySide6 (the window toolkit) is missing — installing it for your user…"
  python3 -m pip install --user PySide6 || python3 -m pip install --user --break-system-packages PySide6 || {
    echo "Could not install PySide6. Install it with your package manager (e.g. 'sudo dnf install python3-pyside6') and run this again."; exit 1; }
fi

mkdir -p "$APP" ~/.local/bin ~/.local/share/applications ~/.config/systemd/user
cp "$SRC"/protonupd.py "$SRC"/protonupd_gui.py "$SRC"/i18n.py "$SRC"/version.py "$SRC"/LICENSE "$APP"/
cp "$SRC"/uninstall.sh "$APP"/ 2>/dev/null || true

cat > ~/.local/bin/proton-updater <<EOW
#!/usr/bin/env bash
cd "$APP"
exec python3 protonupd.py "\$@"
EOW
cat > ~/.local/bin/proton-updater-gui <<EOW
#!/usr/bin/env bash
cd "$APP"
exec python3 protonupd_gui.py "\$@"
EOW
chmod +x ~/.local/bin/proton-updater ~/.local/bin/proton-updater-gui

cat > ~/.local/share/applications/proton-updater.desktop <<EOW
[Desktop Entry]
Type=Application
Name=Proton Updater
Name[uk]=Оновлювач Proton
Comment=Auto-update GE-Proton / proton-rtsp for Steam games
Comment[uk]=Автооновлення GE-Proton / proton-rtsp для ігор Steam
Exec=$HOME/.local/bin/proton-updater-gui
Icon=system-software-update
Categories=Game;Utility;
EOW

cat > ~/.config/systemd/user/proton-updater.service <<EOW
[Unit]
Description=Proton Updater
[Service]
Type=oneshot
ExecStart=$HOME/.local/bin/proton-updater run
EOW
cat > ~/.config/systemd/user/proton-updater.timer <<EOW
[Unit]
Description=Proton Updater - every 30 min
[Timer]
OnBootSec=3min
OnUnitActiveSec=30min
Persistent=true
[Install]
WantedBy=timers.target
EOW
systemctl --user daemon-reload
systemctl --user enable --now proton-updater.timer
echo
echo "Installed. Open “Proton Updater” from your application menu."
echo "Установлено. Відкрий «Оновлювач Proton» у меню програм."
